use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

struct Node;

const ALLOWED: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Returns the host of an http(s) URL, or None if the URL is malformed or
/// uses a form we refuse to interpret (userinfo, backslashes, other schemes).
fn host_of(url: &str) -> Option<String> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    if url.contains('\\') || url.chars().any(|c| c.is_whitespace() || c.is_control()) {
        return None;
    }
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    if authority.is_empty() || authority.contains('@') {
        return None;
    }
    let host = match authority.rfind(':') {
        Some(i) => {
            let port = &authority[i + 1..];
            if port.is_empty() || !port.bytes().all(|b| b.is_ascii_digit()) {
                return None;
            }
            &authority[..i]
        }
        None => authority,
    };
    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            let permitted = match host_of(&url) {
                Some(h) => ALLOWED.iter().any(|a| *a == h),
                None => false,
            };
            if !permitted {
                failures.push(FetchFailure {
                    url,
                    error: "url not permitted".to_string(),
                });
                continue;
            }
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
